/**
 * Level Data - Generated by Stage Editor
 */
const H = 14; 
function joinChunks(chunks) {
    let result = new Array(H).fill("");
    chunks.forEach(chunk => {
        for (let i = 0; i < H; i++) {
            const line = (i < chunk.length) ? chunk[i] : " ".repeat(chunk[0]?.length || 10);
            result[i] += line;
        }
    });
    return result;
}
